 static function fixed(mixed $value,int $places=2,bool $native=false,bool $optional=false):?int {
  $s=str_replace(["\xc2\xa0",' '],'',trim((string)$value));if($s===''){if($optional)return null;throw new Problem('Sumă lipsă.');}
  if(!$native){if(str_contains($s,',')&&str_contains($s,'.'))$s=strrpos($s,',')>strrpos($s,'.')?str_replace(',','.',str_replace('.','',$s)):str_replace(',','',$s);elseif(str_contains($s,','))$s=str_replace(',','.',$s);}
  if(!preg_match('/^(-?)(\d+)(?:\.(\d+))?(?:[eE]([+-]?\d+))?$/D',$s,$m))throw new Problem('Sumă invalidă: '.mb_substr($s,0,40));
  $digits=$m[2].($m[3]??'');$point=strlen($m[2])+(int)($m[4]??0)+$places;if(abs((int)($m[4]??0))>30)throw new Problem('Sumă în afara intervalului.');
  if($point<0){$digits=str_repeat('0',-$point).$digits;$point=0;}if($point>strlen($digits))$digits=str_pad($digits,$point,'0');$integer=ltrim(substr($digits,0,$point),'0')?:'0';$fraction=substr($digits,$point);$round=0;
  if(trim($fraction,'0')!==''){$distance=(float)('0.'.$fraction);if(!$native||min($distance,1-$distance)>0.00001)throw new Problem('Sunt permise maximum '.$places.' zecimale.');$round=$distance>=0.5?1:0;}
  if(strlen($integer)>17)throw new Problem('Sumă prea mare.');return ((int)$integer+$round)*($m[1]==='-'?-1:1);
 }
 static function fixedText(int $value,int $places=5):string{$n=(string)abs($value);$n=str_pad($n,$places+1,'0',STR_PAD_LEFT);return ($value<0?'-':'').substr($n,0,-$places).'.'.substr($n,-$places);}
 static function id(mixed $v,bool $native=false,bool $awb=false):?string{$s=trim((string)$v);if($s==='')return null;if($native){if(!preg_match('/^\d+(?:\.0+)?$/D',$s))throw new Problem('Identificator numeric invalid sau prescurtat.');$s=explode('.',$s)[0];}if(mb_strlen($s)>190)throw new Problem('Identificator prea lung.');if($awb&&!preg_match('/^[0-9]{10,15}$/D',$s))throw new Problem('AWB invalid; sunt necesare cifrele complete.');return $s;}
 static function date(mixed $v,bool $native=false,bool $epoch1904=false):?string{$s=trim((string)$v);if($s==='')return null;if($native&&preg_match('/^\d+(?:\.\d+)?$/D',$s)){$days=(int)explode('.',$s)[0];if($days<1||$days>100000)return null;return (new \DateTimeImmutable($epoch1904?'1904-01-01':'1899-12-30'))->modify('+'.$days.' days')->format('Y-m-d');}if(preg_match('~^(\d{1,2})([-./])(\d{1,2})\2(\d{2}|\d{4})(.*)$~D',$s,$m))$s=sprintf('%02d%s%02d%s%s%s',(int)$m[1],$m[2],(int)$m[3],$m[2],$m[4],$m[5]);$s=preg_replace('/ ([0-9]):/',' 0$1:',$s);foreach(['Y-m-d H:i:s','Y-m-d H:i','Y-m-d','d-m-y H:i:s','d-m-Y H:i:s','d-m-y H:i','d-m-Y H:i','d-m-y','d-m-Y','d.m.Y H:i:s','d.m.Y H:i','d.m.Y','d.m.y','d/m/Y','d/m/y'] as $f){$d=\DateTimeImmutable::createFromFormat('!'.$f,$s);$e=\DateTimeImmutable::getLastErrors();if($d&&$d->format($f)===$s&&(!$e||(!$e['warning_count']&&!$e['error_count'])))return $d->format('Y-m-d');}return null;}
 private static function xml(string $data):\DOMDocument{if(stripos($data,'<!DOCTYPE')!==false||stripos($data,'<!ENTITY')!==false)throw new Problem('XML cu entități externe interzis.');$d=new \DOMDocument();$old=libxml_use_internal_errors(true);try{if(!$d->loadXML($data,LIBXML_NONET|LIBXML_COMPACT))throw new Problem('XML Excel invalid.');}finally{libxml_clear_errors();libxml_use_internal_errors($old);}return $d;}
 private static function text(\DOMNode $n,string $tag):string{if(!$n instanceof \DOMElement)return '';return $n->getElementsByTagName($tag)->item(0)?->textContent??'';}
 private static function col(string $s):int{$n=0;foreach(str_split(preg_replace('/[0-9]+/','',$s)) as $c)$n=$n*26+ord($c)-64;return $n-1;}
 static function book(string $path,string $filename):array {
  if(filesize($path)>40*1024*1024)throw new Problem('Maximum 40 MB per fișier.');$ext=strtolower(pathinfo($filename,PATHINFO_EXTENSION));if($ext==='csv'){$text=file_get_contents($path);if(str_starts_with($text,"\xff\xfe")||str_starts_with($text,"\xfe\xff"))$text=mb_convert_encoding($text,'UTF-8','UTF-16');elseif(!mb_check_encoding($text,'UTF-8'))$text=mb_convert_encoding($text,'UTF-8','Windows-1250');$text=preg_replace('/^\xEF\xBB\xBF/','',$text);$first=strtok($text,"\r\n");$sep=',';$best=0;foreach([',',';',"\t"] as $candidate){$count=count(str_getcsv($first,$candidate,'"',''));if($count>$best){$best=$count;$sep=$candidate;}}$f=fopen('php://temp','w+');fwrite($f,$text);rewind($f);$headers=null;$rows=[];$line=0;while(($row=fgetcsv($f,0,$sep,'"',''))!==false){$line++;if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;if($headers===null){$headers=array_map(fn($v)=>trim((string)$v),$row);if(count(array_unique($headers))!==count($headers)||in_array('',$headers,true))throw new Problem('Antet CSV invalid: coloane goale sau repetate.');continue;}if(count($row)!==count($headers))throw new Problem('Număr diferit de coloane CSV la rândul '.$line);$rows[]=['row'=>$line,'values'=>array_combine($headers,$row),'numeric'=>[]];if(count($rows)>20000)throw new Problem('Maximum 20.000 rânduri pe fișier CSV. Împarte exportul în mai multe fișiere.');}fclose($f);return [['name'=>'CSV','epoch'=>false,'headers'=>$headers??[],'rows'=>$rows]];}
  if($ext!=='xlsx')throw new Problem('Sunt acceptate XLSX și CSV.');$zip=new \ZipArchive();if($zip->open($path)!==true)throw new Problem('Fișier XLSX invalid.');try{$total=0;if($zip->numFiles>2000)throw new Problem('Prea multe componente în XLSX.');for($i=0;$i<$zip->numFiles;$i++){$s=$zip->statIndex($i);$total+=$s['size'];if($total>150*1024*1024)throw new Problem('Registrul decomprimat depășește limita.');}$shared=[];if(($xml=$zip->getFromName('xl/sharedStrings.xml'))!==false)foreach(self::xml($xml)->getElementsByTagName('si') as $n)$shared[]=$n->textContent;$wb=self::xml($zip->getFromName('xl/workbook.xml')?:'');$rels=[];foreach(self::xml($zip->getFromName('xl/_rels/workbook.xml.rels')?:'')->getElementsByTagName('Relationship') as $r)$rels[$r->getAttribute('Id')]=$r->getAttribute('Target');$epoch=in_array($wb->getElementsByTagName('workbookPr')->item(0)?->getAttribute('date1904'),['1','true'],true);$sheets=[];foreach($wb->getElementsByTagName('sheet') as $s){$target=$rels[$s->getAttribute('r:id')]??null;if(!$target)continue;$member=str_starts_with($target,'/')?ltrim($target,'/'):'xl/'.$target;$parts=[];foreach(explode('/',$member) as $x){if($x==='..')array_pop($parts);elseif($x!=='.')$parts[]=$x;}$member=implode('/',$parts);$xml=$zip->getFromName($member);if($xml===false)throw new Problem('Foaie Excel lipsă.');$headers=null;$rows=[];foreach(self::xml($xml)->getElementsByTagName('row') as $row){$values=[];$numeric=[];foreach($row->getElementsByTagName('c') as $c){$col=self::col($c->getAttribute('r'));if($col>1000)throw new Problem('Prea multe coloane.');$v=self::text($c,'v');$type=$c->getAttribute('t');if($type==='s')$v=$shared[(int)$v]??'';elseif($type==='inlineStr')$v=self::text($c,'is');elseif(($type===''||$type==='n')&&$v!=='')$numeric[]=$col;$values[$col]=$v;}if(!array_filter($values,fn($v)=>trim((string)$v)!==''))continue;if($headers===null){$headers=[];for($i=0;$i<=max(array_keys($values));$i++)$headers[]=trim($values[$i]??'');if(count(array_unique($headers))!==count($headers)||in_array('',$headers,true))throw new Problem('Antet Excel invalid.');continue;}$record=[];foreach($headers as $i=>$h)$record[$h]=$values[$i]??'';$rows[]=['row'=>(int)$row->getAttribute('r'),'values'=>$record,'numeric'=>array_map(fn($i)=>$headers[$i]??'', $numeric)];if(count($rows)>20000)throw new Problem('Maximum 20.000 rânduri pe foaie.');}if($headers)$sheets[]=['name'=>$s->getAttribute('name'),'epoch'=>$epoch,'headers'=>$headers,'rows'=>$rows];}return $sheets;}finally{$zip->close();}
 }
 static function read(string $path,string $filename,string $kind,bool $combined=false):array {
  if(!isset(self::HEADERS[$kind]))throw new Problem('Sursă necunoscută.');$book=self::book($path,$filename);$rows=[];$errors=[];$adjustments=[];$rawCount=0;$components=0;$seen=[];$duplicateKeys=[];
  $fanFinancialRows=0;
  foreach($book as $sheet){
   if($kind==='fan'&&in_array('Suma incasata',$sheet['headers'],true)){
    $missing=array_diff(FanTransfers::HEADERS,$sheet['headers']);
    if($missing)throw new Problem('Lipsesc coloanele raportului financiar FAN: '.implode(', ',$missing));
    [$financial,$issues]=FanTransfers::parse($sheet);
    $adjustments=array_merge($adjustments,$financial);
    $errors=array_merge($errors,$issues);
    $rawCount+=count($sheet['rows']);
    $fanFinancialRows+=count($financial);
    continue;
   }
   $missing=array_diff(self::HEADERS[$kind],$sheet['headers']);if($missing)throw new Problem('Lipsesc coloanele: '.implode(', ',$missing));if($kind==='netopia'){[$records,$issues,$bank,$duplicates]=self::netopia($sheet,$combined);$rows=array_merge($rows,$records);$errors=array_merge($errors,$issues);$adjustments=array_merge($adjustments,$bank);$components+=$duplicates;$rawCount+=count($sheet['rows']);continue;}
   foreach($sheet['rows'] as $raw){$rawCount++;$v=$raw['values'];$num=$raw['numeric'];$d=fn($k)=>self::date($v[$k]??'',in_array($k,$num,true),$sheet['epoch']);$a=fn($k,$optional=false)=>self::fixed($v[$k]??'',2,in_array($k,$num,true),$optional);$id=fn($k,$awb=false)=>self::id($v[$k]??'',in_array($k,$num,true),$awb);try{$r=match($kind){'omc'=>['id'=>$id('nr_doc'),'invoice_date'=>$d('data_doc'),'client'=>trim($v['partener']),'amount_cents'=>$a('val_mon'),'balance_cents'=>$a('rest_de_incasat'),'comisionar'=>trim($v['comisionar']),'workplace'=>trim($v['eu_punct_lucru']),'observation'=>trim($v['obs_txt'])], 'fan'=>['id'=>$id('AWB',true),'awb_date'=>$d('Data AWB'),'recipient'=>trim($v['Client Dest.']),'content'=>trim($v['Continut']),'delivery_status_raw'=>trim($v['Status Livrare']),'cash_due_cents'=>$a('Ramburs',true),'transfer_date'=>$d('Data Virament'),'service_raw'=>trim($v['Tip Serviciu'])], 'site'=>['id'=>$id('ID comanda'),'order_date'=>$d('Data'),'payment_date'=>$d('Data platii'),'amount_cents'=>$a('Valoare comanda'),'awb'=>$id('AWB',true),'customer_type'=>trim($v['Tip client']),'client'=>trim($v['Nume client']),'company'=>trim($v['Nume companie']),'payment_method'=>trim($v['Metoda de plata']),'transaction_identifier'=>$id('ID Tranzactie')]};if($kind==='site'){if(array_key_exists('Status plata',$v))$r['_payment_status']=trim($v['Status plata']);if(array_key_exists('Status livrare',$v))$r['_delivery_status']=trim($v['Status livrare']);}if(!$r['id'])throw new Problem('Cheie lipsă.');$hash=hashSource($r);if(isset($seen[$r['id']])){if($seen[$r['id']]!==$hash)throw new Problem('Versiuni diferite pentru aceeași cheie.');$duplicateKeys[]=['key'=>$r['id'],'row'=>$raw['row']];continue;}$seen[$r['id']]=$hash;$rows[]=array_merge($r,['_row'=>$raw['row'],'_sheet'=>$sheet['name']]);}catch(Problem $e){$errors[]=['row'=>$raw['row'],'error'=>$e->getMessage()];}}
  }
  $financialSummary=$fanFinancialRows?['fan_transfers'=>$fanFinancialRows]:[];
  return ['kind'=>$kind,'filename'=>basename($filename),'sha256'=>hash_file('sha256',$path),'records'=>$rows,'errors'=>$errors,'adjustments'=>$adjustments,'summary'=>['raw'=>$rawCount,'unique'=>count($rows),'duplicates'=>count($duplicateKeys),'duplicate_components'=>$components,'invalid'=>count($errors),'adjustments'=>count($adjustments),'combined_confirmed'=>$combined]+$financialSummary,'duplicate_rows'=>$duplicateKeys];
 }
 private static function netopia(array $sheet,bool $combined):array {
  $groups=[];$bank=[];$out=[];$errors=[];$duplicates=0;foreach($sheet['rows'] as $raw){$v=$raw['values'];if(preg_match('/^(?:BankTransfer\s*:)/i',trim($v['Comerciant']))||preg_match('/^Bank\s+transfer\s+BatchId\s*:/i',trim($v['Descriere']))){$bank[]=['row'=>$raw['row'],'type'=>'bank_transfer_fee','values'=>$v];continue;}$id=trim($v['Id']);if($id===''){$bank[]=['row'=>$raw['row'],'type'=>'unclassified_provider_row','values'=>$v];continue;}$groups[$id][]=$raw;}
  foreach($groups as $key=>$lines){try{$unique=[];$fingerprints=[];$dup=0;foreach($lines as $line){$h=hashSource($line['values']);if(isset($fingerprints[$h])){$dup++;continue;}$fingerprints[$h]=true;$unique[]=$line;}if($dup&&!$combined)throw new Problem('Rânduri identice repetate: confirmă că rapoartele au fost combinate.');$duplicates+=$dup;$first=$unique[0]['values'];$identity=[$first['#'],self::date($first['Data operatiei']),self::date($first['Data platii']),nameKey($first['Prenume'].' '.$first['Nume'])];$gross=[];$fee=0;$vat=0;foreach($unique as $line){$v=$line['values'];if(trim($v['Moneda'])!=='RON')throw new Problem('Moneda nu este RON.');if([$v['#'],self::date($v['Data operatiei']),self::date($v['Data platii']),nameKey($v['Prenume'].' '.$v['Nume'])]!==$identity)throw new Problem('Date contradictorii pentru același ID.');foreach(['Creditat','Discount campanie','Discount refund campanie','Colateral retinut','Colateral eliberat'] as $field)if(self::fixed($v[$field],5)!==0)throw new Problem('Creditare/discount/colateral nenul: necesită tratament separat.');$n=self::fixed($v['Procesat']);if($n<0)throw new Problem('Operațiune negativă de verificat separat.');if($n>0)$gross[]=$n;$fee+=self::fixed($v['Comision'],5);$vat+=self::fixed($v['TVA'],5);}if(count($gross)!==1)throw new Problem('Sunt mai multe sume pozitive diferite sau lipsește suma plătită.');$out[]=['id'=>(string)$key,'client'=>trim($first['Prenume'].' '.$first['Nume']),'operation_date'=>$identity[1],'transfer_date'=>$identity[2],'operation_number'=>$first['#'],'gross_amount_cents'=>$gross[0],'commission'=>self::fixedText($fee),'vat'=>self::fixedText($vat),'_row'=>$unique[0]['row'],'_sheet'=>$sheet['name'],'_rows'=>array_column($lines,'row')];}catch(Problem $e){$errors[]=['key'=>(string)$key,'rows'=>array_column($lines,'row'),'error'=>$e->getMessage()];}}
  return [$out,$errors,$bank,$duplicates];
 }
